#include <bits/stdc++.h>
using namespace std;

// Best value of an expression ending at each digit along one line.
int scan(const string &a) {
    int ans = 0, prev = 0, sg = 0;
    bool hasPrev = false, digit = false;
    for (char c : a) {
        if (isdigit((unsigned char)c)) {
            int x = c - '0';
            int v = (sg == 0 || !hasPrev) ? x : max(x, prev + sg * x);
            ans = max(ans, v);
            prev = v, hasPrev = true, sg = 0, digit = true;
        } else if ((c == '+' || c == '-') && digit) {
            sg = c == '+' ? 1 : -1;
            digit = false;
        } else {
            hasPrev = false, sg = 0, digit = false;
        }
    }
    return ans;
}

int main() {
    string line;
    getline(cin, line);
    int h, w;
    stringstream(line) >> h >> w;
    vector<string> g(h);
    for (auto &row : g) {
        getline(cin, row);
        if (!row.empty() && row.back() == '\r') row.pop_back();
    }
    int ans = 0;
    for (auto &row : g) ans = max(ans, scan(row));
    for (int j = 0; j < w; j++) {
        string col;
        for (int i = 0; i < h; i++) col += g[i][j];
        ans = max(ans, scan(col));
    }
    cout << ans << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    // Best value of an expression ending at each digit along one line.
    static int scan(char[] a) {
        int ans = 0, prev = 0, sg = 0;
        boolean hasPrev = false, digit = false;
        for (char c : a) {
            if (c >= '0' && c <= '9') {
                int x = c - '0';
                int v = (sg == 0 || !hasPrev) ? x : Math.max(x, prev + sg * x);
                ans = Math.max(ans, v);
                prev = v;
                hasPrev = true;
                sg = 0;
                digit = true;
            } else if ((c == '+' || c == '-') && digit) {
                sg = c == '+' ? 1 : -1;
                digit = false;
            } else {
                hasPrev = false;
                sg = 0;
                digit = false;
            }
        }
        return ans;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int h = Integer.parseInt(st.nextToken()), w = Integer.parseInt(st.nextToken());
        char[][] g = new char[h][];
        int ans = 0;
        for (int i = 0; i < h; i++) {
            g[i] = br.readLine().toCharArray();
            ans = Math.max(ans, scan(g[i]));
        }
        for (int j = 0; j < w; j++) {
            char[] col = new char[h];
            for (int i = 0; i < h; i++) col[i] = g[i][j];
            ans = Math.max(ans, scan(col));
        }
        System.out.println(ans);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

// scan returns the best value of an expression ending at each digit along one line.
func scan(a []byte) int {
	ans, prev, sg := 0, 0, 0
	hasPrev, digit := false, false
	for _, c := range a {
		if c >= '0' && c <= '9' {
			x := int(c - '0')
			v := x
			if sg != 0 && hasPrev {
				v = max(x, prev+sg*x)
			}
			ans = max(ans, v)
			prev, hasPrev, sg, digit = v, true, 0, true
		} else if (c == '+' || c == '-') && digit {
			sg = 1
			if c == '-' {
				sg = -1
			}
			digit = false
		} else {
			hasPrev, sg, digit = false, 0, false
		}
	}
	return ans
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	lines := strings.Split(string(data), "\n")
	head := strings.Fields(lines[0])
	h, _ := strconv.Atoi(head[0])
	w, _ := strconv.Atoi(head[1])
	g := make([][]byte, h)
	ans := 0
	for i := range g {
		g[i] = []byte(strings.TrimSuffix(lines[1+i], "\r"))
		ans = max(ans, scan(g[i]))
	}
	for j := 0; j < w; j++ {
		col := make([]byte, h)
		for i := range g {
			col[i] = g[i][j]
		}
		ans = max(ans, scan(col))
	}
	fmt.Println(ans)
}
